echo "Regenerando cliente Prisma y sincronizando esquema..."
cd backend
npx prisma generate
npx prisma db push
cd ..

echo "Importando el catalogo de productos (10.634 SKUs, puede tardar unos minutos)..."
cd backend
npm run db:import-surtido
cd ..

echo "Compilando backend..."
cd backend
npm run build
cd ..

echo "Compilando frontend (Backoffice)..."
cd frontend
npm run build
cd ..

echo "Todo compilado e importado correctamente."
echo "Revisa los cambios y luego:"
echo "  git add backend/prisma/schema.prisma backend/prisma/import-surtido.ts backend/prisma/data/surtido-import.json backend/package.json backend/src/modules/products/products.routes.ts frontend/src/pages/masters/ProductsPage.tsx"
echo "  git commit -m 'Importa catalogo real de productos (SURTIDO Getafe): dimensiones, categoria y rotacion ABC'"
echo "  git push"
